/* src/config/fabric.js */
const { Gateway, Wallets } = require('fabric-network');
const fs = require('fs');
const path = require('path');
const yaml = require('yaml');

const CHANNEL_NAME = 'mychannel';
const CHAINCODE_NAME = 'basic'; // Using 'basic' for simplicity or 'mortgage'

async function connectGateway(userId) {
    // Load connection profile; will be generated by test-network
    // Assuming standard test-network path or local file
    const ccpPath = path.resolve(__dirname, '..', '..', '..', 'network', 'organizations', 'peerOrganizations', 'org1.example.com', 'connection-org1.json');

    // Check if CCP exists, if not, we can't connect yet (but code is ready)
    if (!fs.existsSync(ccpPath)) {
        console.warn(`Connection profile not found at ${ccpPath}. Ensure network is up.`);
        // For development/scaffolding without network, we might mock or return null
        // return null; 
    }

    const ccp = JSON.parse(fs.readFileSync(ccpPath, 'utf8'));

    // Create a new file system based wallet for managing identities.
    const walletPath = path.join(__dirname, '..', '..', 'wallet');
    const wallet = await Wallets.newFileSystemWallet(walletPath);

    // Check to see if we've already enrolled the user.
    const identity = await wallet.get(userId);
    if (!identity) {
        throw new Error(`An identity for the user "${userId}" does not exist in the wallet. Run the enrollment script.`);
    }

    // Create a new gateway for connecting to our peer node.
    const gateway = new Gateway();
    await gateway.connect(ccp, { wallet, identity: userId, discovery: { enabled: true, asLocalhost: true } });

    // Get the network (channel) our contract is deployed to.
    const network = await gateway.getNetwork(CHANNEL_NAME);

    // Get the contract from the network.
    const contract = network.getContract(CHAINCODE_NAME);

    return { gateway, contract };
}

module.exports = { connectGateway };
